import {
  migrateDatafnNamespace,
  type DatafnNamespaceMigrationContext,
  type DatafnRoutingEvent,
} from "@datafn/server";
import type { WorkspacePlacement, WorkspacePlacementDirectory } from "./placement.js";
import type { PlacementSqlClient } from "./placement.js";
import { logWorkspaceRoutingEvent } from "./routing.js";

export interface MigrationCheck {
  readonly name: string;
  readonly source: string | number;
  readonly target: string | number;
  readonly matched: boolean;
}

export interface WorkspaceMigrationProof {
  readonly workspaceId: string;
  readonly sourceRegionId: string;
  readonly targetRegionId: string;
  readonly sourceEpoch: number;
  readonly finalEpoch: number;
  readonly startedAt: string;
  readonly completedAt: string;
  readonly checks: readonly MigrationCheck[];
  readonly rollbackTested: boolean;
}

export interface WorkspaceMigrationOperations {
  /** Waits for asynchronous source projections while placement is still active. */
  prepareSource(workspaceId: string): Promise<void>;
  quiesceSource(context: DatafnNamespaceMigrationContext): Promise<void>;
  drainOutboxes(context: DatafnNamespaceMigrationContext): Promise<void>;
  copyDatabase(context: DatafnNamespaceMigrationContext): Promise<void>;
  copyBundles(context: DatafnNamespaceMigrationContext): Promise<void>;
  verifyDatabase(
    context: DatafnNamespaceMigrationContext,
  ): Promise<readonly MigrationCheck[]>;
  verifyBundles(
    context: DatafnNamespaceMigrationContext,
  ): Promise<readonly MigrationCheck[]>;
  rebuildGlobalResourceDirectory(
    context: DatafnNamespaceMigrationContext,
  ): Promise<void>;
  warmTarget(context: DatafnNamespaceMigrationContext): Promise<void>;
  resumeTarget(context: DatafnNamespaceMigrationContext): Promise<void>;
  rollbackSource(
    context: DatafnNamespaceMigrationContext & { readonly cause: unknown },
  ): Promise<void>;
}

export interface WorkspaceMigrationJournal {
  started(input: {
    readonly id: string;
    readonly workspaceId: string;
    readonly sourceRegionId: string;
    readonly targetRegionId: string;
    readonly sourceEpoch: number;
  }): Promise<void>;
  completed(id: string, proof: WorkspaceMigrationProof): Promise<void>;
  completionPending(id: string, proof: WorkspaceMigrationProof): Promise<void>;
  failed(id: string, errorCode: string): Promise<void>;
  /**
   * Returns the newest run whose fenced move finished but whose final journal
   * update failed, so a retry can finalize the stored proof instead of
   * repeating the data move.
   */
  pendingCompletion?(workspaceId: string): Promise<{
    readonly id: string;
    readonly targetRegionId: string;
    readonly proof: WorkspaceMigrationProof;
  } | null>;
}

export class PostgresWorkspaceMigrationJournal implements WorkspaceMigrationJournal {
  constructor(private readonly database: PlacementSqlClient) {}

  async started(input: Parameters<WorkspaceMigrationJournal["started"]>[0]) {
    await this.database.query(
      `INSERT INTO workspace_migration_runs
         (id, workspace_id, source_region_id, target_region_id, source_epoch,
          status, phase, recovery_fence, evidence)
       VALUES ($1, $2, $3, $4, $5, 'running', 'fence', $5, '{}'::jsonb)`,
      [
        input.id,
        input.workspaceId,
        input.sourceRegionId,
        input.targetRegionId,
        input.sourceEpoch,
      ],
    );
  }

  async completed(id: string, proof: WorkspaceMigrationProof) {
    await this.database.query(
      `UPDATE workspace_migration_runs
          SET status = 'completed', phase = 'complete', final_epoch = $2,
              evidence = $3::jsonb, completed_at = now(), updated_at = now()
        WHERE id = $1 AND status = 'running'`,
      [id, proof.finalEpoch, JSON.stringify(proof)],
    );
  }

  async completionPending(id: string, proof: WorkspaceMigrationProof) {
    await this.database.query(
      `UPDATE workspace_migration_runs
          SET phase = 'completion-pending', final_epoch = $2,
              evidence = $3::jsonb, updated_at = now()
        WHERE id = $1 AND status = 'running'`,
      [id, proof.finalEpoch, JSON.stringify(proof)],
    );
  }

  async failed(id: string, errorCode: string) {
    await this.database.query(
      `UPDATE workspace_migration_runs
          SET status = 'failed', phase = 'rollback',
              evidence = evidence || $2::jsonb,
              completed_at = now(), updated_at = now()
        WHERE id = $1 AND status = 'running'`,
      [id, JSON.stringify({ errorCode, rollbackRequired: true })],
    );
  }

  async pendingCompletion(workspaceId: string) {
    const result = await this.database.query<{
      id: string;
      target_region_id: string;
      evidence: WorkspaceMigrationProof;
    }>(
      `SELECT id, target_region_id, evidence
         FROM workspace_migration_runs
        WHERE workspace_id = $1
          AND status = 'running'
          AND phase = 'completion-pending'
        ORDER BY updated_at DESC
        LIMIT 1`,
      [workspaceId],
    );
    const row = result.rows[0];
    if (!row) return null;
    return {
      id: row.id,
      targetRegionId: row.target_region_id,
      proof: row.evidence,
    };
  }
}

export function isWorkspaceMigrationRecoveryPending(
  placement: WorkspacePlacement,
): boolean {
  return (
    placement.state === "moving" ||
    (placement.state === "active" &&
      (placement.migration?.phase === "resume-source" ||
        placement.migration?.phase === "resume-target"))
  );
}

function migrationSource(placement: WorkspacePlacement): {
  readonly regionId: string;
  readonly epoch: number;
} {
  if (!isWorkspaceMigrationRecoveryPending(placement)) {
    return { regionId: placement.regionId, epoch: placement.epoch };
  }
  return {
    regionId:
      placement.migration?.sourceRegionId ??
      placement.previousRegionId ??
      placement.regionId,
    epoch: placement.migration?.sourceEpoch ?? Math.max(1, placement.epoch - 1),
  };
}

/** Composes Skillplane copy/verification hooks with DataFn's fenced move state machine. */
export async function migrateWorkspace(input: {
  readonly directory: WorkspacePlacementDirectory;
  readonly workspaceId: string;
  readonly targetRegionId: string;
  readonly targetDestinationRef?: string;
  readonly operations: WorkspaceMigrationOperations;
  readonly rollbackTested?: boolean;
  readonly now?: () => number;
  readonly onEvent?: (event: DatafnRoutingEvent) => void | Promise<void>;
}): Promise<{
  readonly placement: WorkspacePlacement;
  readonly proof: WorkspaceMigrationProof;
}> {
  const now = input.now ?? Date.now;
  const before = await input.directory.get(input.workspaceId);
  if (!before) {
    throw new Error("WORKSPACE_MIGRATION_SOURCE_NOT_ACTIVE");
  }
  const recovering = isWorkspaceMigrationRecoveryPending(before);
  if (!recovering && before.state !== "active") {
    throw new Error("WORKSPACE_MIGRATION_SOURCE_NOT_ACTIVE");
  }
  const source = migrationSource(before);
  const startedAt = new Date(now()).toISOString();
  const checks: MigrationCheck[] = [];
  // Projection consumers reject events after the placement is fenced as moving,
  // so the asynchronous backlog must converge before entering DataFn's CAS.
  if (!recovering) await input.operations.prepareSource(input.workspaceId);
  const placement = await migrateDatafnNamespace({
    directory: input.directory,
    namespace: input.workspaceId,
    targetRegionId: input.targetRegionId,
    ...(input.targetDestinationRef
      ? { targetDestinationRef: input.targetDestinationRef }
      : {}),
    hooks: {
      quiesceSource: (context) => input.operations.quiesceSource(context),
      drainPermissionDirectory: (context) => input.operations.drainOutboxes(context),
      async copyTenantData(context) {
        await input.operations.copyDatabase(context);
        await input.operations.copyBundles(context);
      },
      async validateTenantData(context) {
        checks.push(...(await input.operations.verifyDatabase(context)));
        checks.push(...(await input.operations.verifyBundles(context)));
        if (checks.length === 0 || checks.some((check) => !check.matched)) {
          throw new Error("WORKSPACE_MIGRATION_VERIFICATION_FAILED");
        }
      },
      rebuildPermissionDirectory: (context) =>
        input.operations.rebuildGlobalResourceDirectory(context),
      warmTarget: (context) => input.operations.warmTarget(context),
      resumeTarget: (context) => input.operations.resumeTarget(context),
      rollbackSource: (context) => input.operations.rollbackSource(context),
    },
    now,
    onEvent:
      input.onEvent ??
      ((event) => {
        logWorkspaceRoutingEvent("migration", event);
      }),
  });
  return {
    placement,
    proof: {
      workspaceId: input.workspaceId,
      sourceRegionId: source.regionId,
      targetRegionId: input.targetRegionId,
      sourceEpoch: source.epoch,
      finalEpoch: placement.epoch,
      startedAt,
      completedAt: new Date(now()).toISOString(),
      checks,
      rollbackTested: input.rollbackTested ?? false,
    },
  };
}

/** Exercises the real fenced rollback path before a production cutover. */
export async function runWorkspaceRollbackDrill(input: {
  readonly directory: WorkspacePlacementDirectory;
  readonly workspaceId: string;
  readonly targetRegionId: string;
  readonly targetDestinationRef?: string;
  readonly operations: WorkspaceMigrationOperations;
  readonly now?: () => number;
  readonly onEvent?: (event: DatafnRoutingEvent) => void | Promise<void>;
}): Promise<void> {
  const source = await input.directory.get(input.workspaceId);
  if (source?.state !== "active") {
    throw new Error("WORKSPACE_MIGRATION_SOURCE_NOT_ACTIVE");
  }
  const operations: WorkspaceMigrationOperations = {
    prepareSource: (workspaceId) => input.operations.prepareSource(workspaceId),
    quiesceSource: (context) => input.operations.quiesceSource(context),
    drainOutboxes: (context) => input.operations.drainOutboxes(context),
    copyDatabase: (context) => input.operations.copyDatabase(context),
    copyBundles: (context) => input.operations.copyBundles(context),
    verifyDatabase: (context) => input.operations.verifyDatabase(context),
    verifyBundles: (context) => input.operations.verifyBundles(context),
    rebuildGlobalResourceDirectory: (context) =>
      input.operations.rebuildGlobalResourceDirectory(context),
    async warmTarget(context) {
      await input.operations.warmTarget(context);
      throw new Error("WORKSPACE_MIGRATION_ROLLBACK_DRILL");
    },
    resumeTarget: (context) => input.operations.resumeTarget(context),
    rollbackSource: (context) => input.operations.rollbackSource(context),
  };
  try {
    await migrateWorkspace({ ...input, operations });
    throw new Error("WORKSPACE_MIGRATION_ROLLBACK_DRILL_DID_NOT_FAIL");
  } catch (error) {
    if (
      !(error instanceof Error) ||
      error.message !== "WORKSPACE_MIGRATION_ROLLBACK_DRILL"
    ) {
      throw error;
    }
  }
  const restored = await input.directory.get(input.workspaceId);
  if (
    restored?.state !== "active" ||
    restored.regionId !== source.regionId ||
    restored.epoch <= source.epoch
  ) {
    throw new Error("WORKSPACE_MIGRATION_ROLLBACK_DRILL_FAILED");
  }
}

/** Runs the fenced move while persisting operator-visible evidence. */
export async function migrateWorkspaceWithJournal(
  input: Parameters<typeof migrateWorkspace>[0] & {
    readonly journal: WorkspaceMigrationJournal;
    readonly migrationId?: string;
  },
): Promise<{
  readonly migrationId: string;
  readonly placement: WorkspacePlacement;
  readonly proof: WorkspaceMigrationProof;
}> {
  const source = await input.directory.get(input.workspaceId);
  if (
    !source ||
    (source.state !== "active" && !isWorkspaceMigrationRecoveryPending(source))
  ) {
    throw new Error("WORKSPACE_MIGRATION_SOURCE_NOT_ACTIVE");
  }
  // A previous run may have activated the target and then failed its final
  // journal update. Retrying that run reaches this entrypoint with the
  // placement already active at the target, so finalize the stored proof
  // instead of rejecting the retry or repeating the data move.
  const pending = await input.journal.pendingCompletion?.(input.workspaceId);
  if (pending?.targetRegionId === input.targetRegionId) {
    try {
      await input.journal.completed(pending.id, pending.proof);
    } catch (error) {
      const completion = new Error("WORKSPACE_MIGRATION_JOURNAL_COMPLETION_FAILED");
      completion.cause = error;
      throw completion;
    }
    return { migrationId: pending.id, placement: source, proof: pending.proof };
  }
  const origin = migrationSource(source);
  const migrationId = input.migrationId ?? `workspace-migration:${crypto.randomUUID()}`;
  await input.journal.started({
    id: migrationId,
    workspaceId: input.workspaceId,
    sourceRegionId: origin.regionId,
    targetRegionId: input.targetRegionId,
    sourceEpoch: origin.epoch,
  });
  let result: Awaited<ReturnType<typeof migrateWorkspace>>;
  try {
    result = await migrateWorkspace(input);
  } catch (error) {
    const code =
      error instanceof Error && /^[A-Z0-9_:-]{1,160}$/u.test(error.message)
        ? error.message
        : "WORKSPACE_MIGRATION_FAILED";
    await input.journal.failed(migrationId, code).catch(() => undefined);
    throw error;
  }
  try {
    await input.journal.completed(migrationId, result.proof);
    return { migrationId, ...result };
  } catch (error) {
    await input.journal
      .completionPending(migrationId, result.proof)
      .catch(() => undefined);
    const completion = new Error("WORKSPACE_MIGRATION_JOURNAL_COMPLETION_FAILED");
    completion.cause = error;
    throw completion;
  }
}

#!/usr/bin/env node

import { Pool } from "pg";
import {
  PostgresWorkspaceMigrationJournal,
  PostgresWorkspaceMigrationOperations,
  createPostgresWorkspacePlacementDirectory,
  isWorkspaceMigrationRecoveryPending,
  migrateWorkspaceWithJournal,
  runWorkspaceRollbackDrill,
} from "../packages/control-plane/dist/index.js";
import {
  isMain,
  parseDirectPostgresUrl,
  requireEnvironment,
} from "./lib/production-deployment.mjs";
import {
  requireBucketName,
  WranglerR2MigrationStore,
} from "./lib/wrangler-r2-migration-store.mjs";

function bucketName(name) {
  return requireBucketName(requireEnvironment(name), name);
}

export function assertDistinctMigrationBuckets(sourceBucket, targetBucket) {
  if (sourceBucket === targetBucket) {
    throw new Error(
      "SKILLPLANE_SOURCE_BUCKET and SKILLPLANE_TARGET_BUCKET must be distinct",
    );
  }
  return { sourceBucket, targetBucket };
}

export function requiresWorkspaceRollbackDrill(placement) {
  return placement === null || !isWorkspaceMigrationRecoveryPending(placement);
}

export function assertDistinctMigrationDatabases(databases) {
  if (
    new Set(Object.values(databases).map(({ fingerprint }) => fingerprint)).size !== 3
  ) {
    throw new Error("Migration control, source, and target databases must be distinct");
  }
  return databases;
}

export function migrationSourceRegionId(placement) {
  if (!placement) {
    throw new Error("WORKSPACE_MIGRATION_SOURCE_NOT_ACTIVE");
  }
  if (!isWorkspaceMigrationRecoveryPending(placement)) {
    return placement.regionId;
  }
  return (
    placement.migration?.sourceRegionId ??
    placement.previousRegionId ??
    placement.regionId
  );
}

export function assertMigrationDatabaseRegions(input) {
  const sourceRegionId = migrationSourceRegionId(input.placement);
  if (sourceRegionId === input.targetRegionId) {
    throw new Error("Workspace migration source and target regions must be distinct");
  }
  const sourceDatabase = input.regionalDatabases[sourceRegionId];
  const targetDatabase = input.regionalDatabases[input.targetRegionId];
  if (
    !sourceDatabase ||
    input.databases.source.fingerprint !== sourceDatabase.fingerprint
  ) {
    throw new Error(
      `SKILLPLANE_SOURCE_DATABASE_URL must identify the ${sourceRegionId} cell database`,
    );
  }
  if (
    !targetDatabase ||
    input.databases.target.fingerprint !== targetDatabase.fingerprint
  ) {
    throw new Error(
      `SKILLPLANE_TARGET_DATABASE_URL must identify the ${input.targetRegionId} cell database`,
    );
  }
  return { sourceRegionId, targetRegionId: input.targetRegionId };
}

export function assertMigrationBucketRegions(input) {
  const expectedSource = input.regionalBuckets[input.sourceRegionId];
  const expectedTarget = input.regionalBuckets[input.targetRegionId];
  if (!expectedSource || input.buckets.sourceBucket !== expectedSource) {
    throw new Error(
      `SKILLPLANE_SOURCE_BUCKET must name the ${input.sourceRegionId} cell bucket`,
    );
  }
  if (!expectedTarget || input.buckets.targetBucket !== expectedTarget) {
    throw new Error(
      `SKILLPLANE_TARGET_BUCKET must name the ${input.targetRegionId} cell bucket`,
    );
  }
  return { sourceRegionId: input.sourceRegionId, targetRegionId: input.targetRegionId };
}

function cellDatabaseEnvironment(regionId) {
  return `SKILLPLANE_CELL_${regionId.replaceAll("-", "_").toUpperCase()}_DATABASE_URL`;
}

function cellBucketEnvironment(regionId) {
  return `SKILLPLANE_CELL_${regionId.replaceAll("-", "_").toUpperCase()}_BUCKET`;
}

export async function migrateConfiguredWorkspace() {
  const workspaceId = requireEnvironment("SKILLPLANE_WORKSPACE_ID", {
    pattern: /^[A-Za-z0-9:_-]{1,180}$/u,
  });
  const targetRegionId = requireEnvironment("SKILLPLANE_TARGET_REGION_ID", {
    pattern: /^[a-z0-9][a-z0-9-]{0,62}$/u,
  });
  const buckets = assertDistinctMigrationBuckets(
    bucketName("SKILLPLANE_SOURCE_BUCKET"),
    bucketName("SKILLPLANE_TARGET_BUCKET"),
  );
  const databases = assertDistinctMigrationDatabases({
    control: parseDirectPostgresUrl(
      requireEnvironment("SKILLPLANE_CONTROL_DATABASE_URL"),
      "SKILLPLANE_CONTROL_DATABASE_URL",
    ),
    source: parseDirectPostgresUrl(
      requireEnvironment("SKILLPLANE_SOURCE_DATABASE_URL"),
      "SKILLPLANE_SOURCE_DATABASE_URL",
    ),
    target: parseDirectPostgresUrl(
      requireEnvironment("SKILLPLANE_TARGET_DATABASE_URL"),
      "SKILLPLANE_TARGET_DATABASE_URL",
    ),
  });
  const control = new Pool({
    connectionString: databases.control.url,
    application_name: "skillplane-workspace-migration-control",
    max: 2,
  });
  let source;
  let target;
  try {
    const directory = createPostgresWorkspacePlacementDirectory(control);
    const journal = new PostgresWorkspaceMigrationJournal(control);
    const placement = await directory.get(workspaceId);
    // When a previous run activated the target but failed its final journal
    // update, the placement is already active at the target region. Region
    // assertions and the rollback drill only apply to an actual data move;
    // a completion-pending run is finalized from its stored proof instead.
    const pendingCompletion = await journal.pendingCompletion(workspaceId);
    const finalizingCompletion = pendingCompletion?.targetRegionId === targetRegionId;
    if (!finalizingCompletion) {
      const sourceRegionId = migrationSourceRegionId(placement);
      const regionIds = [...new Set([sourceRegionId, targetRegionId])];
      const regionalDatabases = Object.fromEntries(
        regionIds.map((regionId) => {
          const environment = cellDatabaseEnvironment(regionId);
          return [
            regionId,
            parseDirectPostgresUrl(requireEnvironment(environment), environment),
          ];
        }),
      );
      assertMigrationDatabaseRegions({
        placement,
        targetRegionId,
        databases,
        regionalDatabases,
      });
      // The copied bundles are verified against the same buckets they are
      // written to, so a wrong-but-distinct bucket would pass every check while
      // the target cell reads from its own configured bucket. Bind both
      // buckets to their placement regions exactly like the databases above.
      const regionalBuckets = Object.fromEntries(
        regionIds.map((regionId) => {
          const environment = cellBucketEnvironment(regionId);
          return [regionId, bucketName(environment)];
        }),
      );
      assertMigrationBucketRegions({
        sourceRegionId,
        targetRegionId,
        buckets,
        regionalBuckets,
      });
    }
    source = new Pool({
      connectionString: databases.source.url,
      application_name: "skillplane-workspace-migration-source",
      max: 2,
    });
    target = new Pool({
      connectionString: databases.target.url,
      application_name: "skillplane-workspace-migration-target",
      max: 2,
    });
    const operations = new PostgresWorkspaceMigrationOperations(
      source,
      target,
      control,
      new WranglerR2MigrationStore(buckets.sourceBucket),
      new WranglerR2MigrationStore(buckets.targetBucket),
    );
    if (!finalizingCompletion && requiresWorkspaceRollbackDrill(placement)) {
      await runWorkspaceRollbackDrill({
        directory,
        workspaceId,
        targetRegionId,
        operations,
      });
    }
    return await migrateWorkspaceWithJournal({
      directory,
      journal,
      workspaceId,
      targetRegionId,
      operations,
      rollbackTested: true,
    });
  } finally {
    await Promise.allSettled(
      [source, target, control].filter(Boolean).map((pool) => pool.end()),
    );
  }
}

if (isMain(import.meta.url)) {
  process.stdout.write(
    `${JSON.stringify({ ok: true, ...(await migrateConfiguredWorkspace()) }, null, 2)}\n`,
  );
}

#!/usr/bin/env node

import { dirname } from "node:path";
import {
  backfillLegacyPublicSkillProjections,
  migrateLegacyWorkspaceBatch,
} from "../packages/control-plane/dist/index.js";
import { migrateDatabase } from "../packages/db/dist/src/index.js";
import { GLOBAL_CONTROL_TABLES } from "../packages/control-plane/dist/table-ownership.js";
import { Pool } from "pg";
import {
  isMain,
  productionBucket,
  requireCleanSourceRevision,
  requireEnvironment,
  requireSecretEnvironment,
} from "./lib/production-deployment.mjs";
import {
  assertRecentTopologyBackups,
  productionTopologyDatabases,
  topologyBackupStatePath,
  verifyProductionTopologyDatabaseOwnership,
  writeTopologyMigrationSafetyState,
} from "./lib/production-topology-safety.mjs";
import { backupProductionDatabase } from "./production-backup.mjs";
import { readProductionTopology } from "./lib/topology-deployment.mjs";
import {
  requireBucketName,
  WranglerR2MigrationStore,
} from "./lib/wrangler-r2-migration-store.mjs";

function regionBucketEnvironment(regionId) {
  return `SKILLPLANE_CELL_${regionId.replaceAll("-", "_").toUpperCase()}_BUCKET`;
}

export function assertDistinctTopologyCutoverBuckets(
  legacyBucketName,
  initialCellBucketName,
  additionalBucketNames = [],
) {
  const names = [legacyBucketName, initialCellBucketName, ...additionalBucketNames];
  if (new Set(names).size !== names.length) {
    throw new Error("Legacy, public, and regional topology buckets must be distinct");
  }
  return { legacyBucketName, initialCellBucketName };
}

export async function prepareLegacyControlDatabase(
  databaseUrl,
  migrate = migrateDatabase,
) {
  // The legacy database remains the regional copy source until cutover. Apply
  // every source-side fence/outbox migration before switching its ownership
  // role to control and eventually pruning regional tables.
  await migrate(databaseUrl, {
    role: "combined",
    initialWorkspaceRegion: "legacy",
    finalizePhysicalOwnership: false,
  });
  return migrate(databaseUrl, {
    role: "control",
    initialWorkspaceRegion: "legacy",
    finalizePhysicalOwnership: false,
  });
}

async function prepareRegionalDatabase(databaseUrl, regionId) {
  await migrateDatabase(databaseUrl, {
    role: "regional",
    finalizePhysicalOwnership: false,
  });
  const pool = new Pool({
    connectionString: databaseUrl,
    application_name: `skillplane-topology-cell-safety-${regionId}`,
    max: 1,
  });
  try {
    for (const table of GLOBAL_CONTROL_TABLES) {
      const relation = await pool.query("SELECT to_regclass($1)::text AS relation", [
        `public.${table}`,
      ]);
      if (!relation.rows[0]?.relation) continue;
      const rows = await pool.query(`SELECT 1 FROM "${table}" LIMIT 1`);
      if (rows.rowCount !== 0) {
        throw new Error(`TOPOLOGY_CELL_GLOBAL_DATA_PRESENT:${regionId}:${table}`);
      }
    }
  } finally {
    await pool.end();
  }
  return migrateDatabase(databaseUrl, { role: "regional" });
}

export async function backupTopologyDatabases(databases, options = {}) {
  const backup = options.backupDatabase ?? backupProductionDatabase;
  const passphrase =
    options.passphrase ?? requireSecretEnvironment("SKILLPLANE_BACKUP_ENCRYPTION_KEY");
  const control = await backup({
    database: databases.control,
    passphrase,
    stateDirectory: dirname(topologyBackupStatePath()),
  });
  const cells = {};
  for (const [regionId, database] of Object.entries(databases.cells)) {
    cells[regionId] = await backup({
      database,
      passphrase,
      stateDirectory: dirname(topologyBackupStatePath(regionId)),
    });
  }
  return assertRecentTopologyBackups({ control, cells }, databases);
}

export async function completeTopologyCutover(controlPool, targetRegionId) {
  const client = await controlPool.connect();
  try {
    await client.query("BEGIN");
    const state = await client.query(
      `SELECT state
         FROM topology_cutover_state
        WHERE id = 'legacy-to-cells'
        FOR UPDATE`,
    );
    if (state.rows[0]?.state !== "copying") {
      throw new Error("TOPOLOGY_CUTOVER_NOT_COPYING");
    }
    const incomplete = await client.query(
      `SELECT count(*)::text AS count
         FROM workspaces workspace
         LEFT JOIN workspace_placements placement
           ON placement.workspace_id = workspace.id
        WHERE placement.workspace_id IS NULL
           OR placement.state <> 'active'
           OR placement.region_id <> $1`,
      [targetRegionId],
    );
    if (incomplete.rows[0]?.count !== "0") {
      throw new Error("TOPOLOGY_CUTOVER_PLACEMENTS_INCOMPLETE");
    }
    const completed = await client.query(
      `UPDATE topology_cutover_state
          SET state = 'complete', target_region_id = $1,
              completed_at = now(), updated_at = now()
        WHERE id = 'legacy-to-cells' AND state = 'copying'
        RETURNING id`,
      [targetRegionId],
    );
    if (completed.rowCount !== 1) {
      throw new Error("TOPOLOGY_CUTOVER_COMPLETION_CONFLICT");
    }
    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK").catch(() => undefined);
    throw error;
  } finally {
    client.release();
  }
}

export async function migrateTopologyDatabases(options = {}) {
  const manifest = options.manifest ?? (await readProductionTopology());
  const sourceRevision = options.sourceRevision ?? requireCleanSourceRevision();
  const databases =
    options.databases ??
    productionTopologyDatabases(manifest, {
      controlDatabaseUrl: options.controlDatabaseUrl,
      cells: options.cells,
      productionDatabase: options.productionDatabase,
    });
  const initialWorkspaceRegion = manifest.cells[0]?.regionId;
  if (!initialWorkspaceRegion) {
    throw new Error("The topology must declare an initial workspace cell");
  }
  const topologyBuckets = {
    legacy: requireBucketName(
      options.legacyBucketName ??
        process.env.SKILLPLANE_LEGACY_BUCKET ??
        productionBucket,
      "SKILLPLANE_LEGACY_BUCKET",
    ),
    public: requireBucketName(
      options.publicBucketName ??
        process.env.SKILLPLANE_PUBLIC_BUCKET ??
        "skillplane-public-bundles",
      "SKILLPLANE_PUBLIC_BUCKET",
    ),
    cells: Object.fromEntries(
      manifest.cells.map((cell) => [
        cell.regionId,
        requireBucketName(
          options.cellBucketNames?.[cell.regionId] ??
            (cell.regionId === initialWorkspaceRegion
              ? options.initialCellBucketName
              : undefined) ??
            requireEnvironment(regionBucketEnvironment(cell.regionId)),
          regionBucketEnvironment(cell.regionId),
        ),
      ]),
    ),
  };
  assertDistinctTopologyCutoverBuckets(
    topologyBuckets.legacy,
    topologyBuckets.cells[initialWorkspaceRegion],
    [
      topologyBuckets.public,
      ...Object.entries(topologyBuckets.cells)
        .filter(([regionId]) => regionId !== initialWorkspaceRegion)
        .map(([, name]) => name),
    ],
  );
  // Capture and verify every database before the first schema or data mutation.
  // The resulting digests are bound into the exact-commit migration evidence.
  const backups = await backupTopologyDatabases(databases, {
    backupDatabase: options.backupDatabase,
    passphrase: options.backupPassphrase,
  });
  const controlUrl = databases.control.url;
  const cellUrls = Object.fromEntries(
    manifest.cells.map((cell) => [cell.regionId, databases.cells[cell.regionId].url]),
  );

  const cells = {};
  for (const cell of manifest.cells) {
    cells[cell.regionId] = await prepareRegionalDatabase(
      cellUrls[cell.regionId],
      cell.regionId,
    );
  }

  const preparedControl = await prepareLegacyControlDatabase(controlUrl);
  const controlPool = new Pool({
    connectionString: controlUrl,
    application_name: "skillplane-topology-cutover-control",
    max: 3,
  });
  const targetPool = new Pool({
    connectionString: cellUrls[initialWorkspaceRegion],
    application_name: "skillplane-topology-cutover-target",
    max: 3,
  });
  let cutover;
  let projection;
  let alreadyComplete = false;
  try {
    const state = await controlPool.query(
      `SELECT state,
              to_regclass('public.skills')::text AS regional_table
         FROM topology_cutover_state
        WHERE id = 'legacy-to-cells'`,
    );
    const current = state.rows[0];
    if (current?.state === "complete" && current.regional_table === null) {
      alreadyComplete = true;
    } else if (current?.state === "complete") {
      cutover = { migrated: [], verifiedExisting: [] };
      projection = { projected: 0 };
    } else {
      await controlPool.query(
        `UPDATE topology_cutover_state
            SET state = 'copying', target_region_id = $1,
                started_at = COALESCE(started_at, now()),
                completed_at = NULL, updated_at = now()
          WHERE id = 'legacy-to-cells'`,
        [initialWorkspaceRegion],
      );
      const cutoverBuckets = assertDistinctTopologyCutoverBuckets(
        topologyBuckets.legacy,
        topologyBuckets.cells[initialWorkspaceRegion],
        [topologyBuckets.public],
      );
      const sourceObjects =
        options.sourceObjects ??
        new WranglerR2MigrationStore(cutoverBuckets.legacyBucketName);
      const regionalObjects =
        options.regionalObjects ??
        new WranglerR2MigrationStore(cutoverBuckets.initialCellBucketName);
      const publicObjects =
        options.publicObjects ?? new WranglerR2MigrationStore(topologyBuckets.public);
      cutover = await migrateLegacyWorkspaceBatch({
        control: controlPool,
        source: controlPool,
        target: targetPool,
        sourceObjects,
        targetObjects: regionalObjects,
        targetRegionId: initialWorkspaceRegion,
      });
      projection = await backfillLegacyPublicSkillProjections({
        control: controlPool,
        regional: targetPool,
        regionalObjects,
        publicObjects,
        regionId: initialWorkspaceRegion,
      });
      await completeTopologyCutover(controlPool, initialWorkspaceRegion);
    }
  } finally {
    await Promise.allSettled([controlPool.end(), targetPool.end()]);
  }

  const control = alreadyComplete
    ? preparedControl
    : await migrateDatabase(controlUrl, {
        role: "control",
        initialWorkspaceRegion,
        workspaceRegions: manifest.cells.map((cell) => cell.regionId),
      });
  await verifyProductionTopologyDatabaseOwnership(manifest, databases);
  const safety = await writeTopologyMigrationSafetyState({
    sourceRevision,
    manifest,
    databases,
    backups,
    control,
    cells,
    cutoverComplete: true,
  });
  return {
    ok: true,
    control,
    cells,
    cutover: cutover ?? { migrated: [], verifiedExisting: [] },
    projection: projection ?? { projected: 0 },
    alreadyComplete,
    safety,
  };
}

if (isMain(import.meta.url)) {
  process.stdout.write(
    `${JSON.stringify(await migrateTopologyDatabases(), null, 2)}\n`,
  );
}

