set -e
repo=/Users/serro/Documents/dev/n/worktrees/skillplane/SKI-13
snapshot="$(mktemp -d /tmp/skillplane-pr8-round7.XXXXXX)"
token="$(gh auth token --hostname github.com --user thyaravind)"
query='query($endCursor: String) {
  repository(owner: "21nCo", name: "skillplane") {
    pullRequest(number: 8) {
      reviewThreads(first: 100, after: $endCursor) {
        nodes {
          isResolved
          path
          comments(first: 20) {
            nodes {
              body
              author { login }
              createdAt
              outdated
              url
              diffHunk
              originalLine
              line
            }
          }
        }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
}'
cd "$repo"
GH_TOKEN="$token" gh api graphql --paginate --slurp -f query="$query" > "$snapshot/threads.json"
GH_TOKEN="$token" gh pr view 8 --repo 21nCo/skillplane --json number,headRefName,headRefOid,baseRefName,reviews,comments,updatedAt,url,state > "$snapshot/pr.json"
GH_TOKEN="$token" gh api --paginate --slurp repos/21nCo/skillplane/pulls/8/comments > "$snapshot/inline-comments.json"
printf 'snapshot=%s\n' "$snapshot"
python3 - "$snapshot" <<'PY'
import json, pathlib, sys
root = pathlib.Path(sys.argv[1])
pages = json.loads((root / "threads.json").read_text())
threads = []
for page in pages:
    threads.extend(page["data"]["repository"]["pullRequest"]["reviewThreads"]["nodes"])
pr = json.loads((root / "pr.json").read_text())
inline_pages = json.loads((root / "inline-comments.json").read_text())
inline = [item for page in inline_pages for item in page]
print(f"pr={pr['url']}")
print(f"head_branch={pr['headRefName']}")
print(f"head_sha={pr['headRefOid']}")
print(f"state={pr['state']}")
print(f"threads={len(threads)}")
print(f"unresolved={sum(not thread['isResolved'] for thread in threads)}")
print(f"reviews={len(pr.get('reviews') or [])}")
print(f"issue_comments={len(pr.get('comments') or [])}")
print(f"inline_comments={len(inline)}")
PY

